<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('programme_manager');
require_once __DIR__ . '/_management_suite_helpers.php';
$user=current_user();$conn=Database::getConnection();$managerId=(int)($user['id']??$user['user_id']??0);
if($managerId<=0){http_response_code(403);exit('Invalid Programme Manager account.');}
$currentPage='stakeholders';$pageTitle='Stakeholder Engagement';$flashes=render_flashes();$errors=[];
$ready=pm_table_exists($conn,'programme_stakeholders')&&pm_table_exists($conn,'programme_stakeholder_engagements');
$programmes=pm_suite_programmes($conn,$managerId);$cohorts=pm_suite_cohorts($conn,$managerId);
$types=['Partner','Employer','Training Provider','Government','Community','Sponsor','Internal Team','Other'];
$channels=['meeting'=>'Meeting','phone'=>'Phone call','email'=>'Email','site_visit'=>'Site visit','workshop'=>'Workshop','other'=>'Other'];
$actionStatuses=['open'=>'Open','in_progress'=>'In progress','completed'=>'Completed','overdue'=>'Overdue'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!validate_csrf())$errors[]='Session validation failed. Refresh and try again.';
 elseif(!$ready)$errors[]='Import database/programme_stakeholder_benefits.sql before using stakeholder tracking.';
 else{
  $action=(string)($_POST['action']??'create_stakeholder');
  if($action==='update_action'){
   $engagementId=(int)($_POST['engagement_id']??0);$status=(string)($_POST['action_status']??'open');
   if(!isset($actionStatuses[$status]))$errors[]='Choose a valid action status.';
   if(!$errors){$s=$conn->prepare("UPDATE programme_stakeholder_engagements e JOIN programmes p ON p.id=e.programme_id SET e.action_status=? WHERE e.id=? AND p.programme_manager_id=? AND e.action_required IS NOT NULL AND e.action_required<>''");if($s){$s->bind_param('sii',$status,$engagementId,$managerId);$s->execute();$changed=$s->affected_rows;$s->close();if($changed>=0){set_flash('success','Action updated','The engagement action status has been updated.');safe_redirect('programme/stakeholders.php');}}$errors[]='The action could not be updated.';}
  }elseif($action==='record_engagement'){
   $stakeholderId=(int)($_POST['stakeholder_id']??0);$date=trim((string)($_POST['engagement_date']??''));$channel=(string)($_POST['channel']??'meeting');$subject=trim((string)($_POST['subject']??''));$summary=trim((string)($_POST['engagement_summary']??''));$contribution=trim((string)($_POST['contribution']??''));$actionRequired=trim((string)($_POST['action_required']??''));$owner=trim((string)($_POST['action_owner']??''));$due=trim((string)($_POST['action_due']??''));
   $s=$conn->prepare('SELECT s.id,s.programme_id FROM programme_stakeholders s JOIN programmes p ON p.id=s.programme_id WHERE s.id=? AND p.programme_manager_id=?');$stakeholder=null;if($s){$s->bind_param('ii',$stakeholderId,$managerId);$s->execute();$stakeholder=$s->get_result()->fetch_assoc();$s->close();}
   $dt=DateTime::createFromFormat('!Y-m-d\TH:i',$date);if(!$stakeholder)$errors[]='Choose a stakeholder within your assigned programmes.';if(!$dt||$dt->format('Y-m-d\TH:i')!==$date)$errors[]='Enter a valid engagement date and time.';if(!isset($channels[$channel]))$errors[]='Choose a valid engagement channel.';if($subject===''||mb_strlen($subject)>180)$errors[]='Enter an engagement subject of up to 180 characters.';if($actionRequired!==''&&$owner==='')$errors[]='Assign an owner for the outstanding action.';$dueValue=null;if($due!==''){$d=DateTime::createFromFormat('!Y-m-d',$due);if(!$d||$d->format('Y-m-d')!==$due)$errors[]='Enter a valid action due date.';else $dueValue=$due;}if(!$errors){$programId=(int)$stakeholder['programme_id'];$dateValue=$dt->format('Y-m-d H:i:s');$summaryValue=$summary?:null;$contributionValue=$contribution?:null;$actionValue=$actionRequired?:null;$ownerValue=$owner?:null;$statusValue=$actionRequired===''?'not_required':'open';$s=$conn->prepare('INSERT INTO programme_stakeholder_engagements(stakeholder_id,programme_id,engagement_date,channel,subject,engagement_summary,contribution,action_required,action_owner,action_due,action_status,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iisssssssssi',$stakeholderId,$programId,$dateValue,$channel,$subject,$summaryValue,$contributionValue,$actionValue,$ownerValue,$dueValue,$statusValue,$managerId);if($s->execute()){$s->close();set_flash('success','Engagement recorded','The stakeholder engagement has been saved.');safe_redirect('programme/stakeholders.php');}$s->close();}$errors[]='The engagement could not be saved.';}
  }else{
   $pid=(int)($_POST['programme_id']??0);$cid=(int)($_POST['cohort_id']??0);$name=trim((string)($_POST['stakeholder_name']??''));$organisation=trim((string)($_POST['organisation']??''));$type=(string)($_POST['stakeholder_type']??'Partner');$role=trim((string)($_POST['role_responsibility']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$influence=(string)($_POST['influence_level']??'medium');$interest=(string)($_POST['interest_level']??'medium');$notes=trim((string)($_POST['notes']??''));
   if(!pm_suite_valid_scope($conn,$pid,$cid,$managerId))$errors[]='Choose a programme/cohort within your assigned scope.';if($name===''||mb_strlen($name)>160)$errors[]='Enter a stakeholder name of up to 160 characters.';if(!in_array($type,$types,true))$errors[]='Choose a valid stakeholder type.';if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Enter a valid email address.';if(!in_array($influence,['low','medium','high'],true)||!in_array($interest,['low','medium','high'],true))$errors[]='Choose valid influence and interest levels.';
   if(!$errors){$cohortValue=$cid?:null;$orgValue=$organisation?:null;$roleValue=$role?:null;$emailValue=$email?:null;$phoneValue=$phone?:null;$notesValue=$notes?:null;$s=$conn->prepare('INSERT INTO programme_stakeholders(programme_id,cohort_id,stakeholder_name,organisation,stakeholder_type,role_responsibility,email,phone,influence_level,interest_level,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');if($s){$s->bind_param('iisssssssssi',$pid,$cohortValue,$name,$orgValue,$type,$roleValue,$emailValue,$phoneValue,$influence,$interest,$notesValue,$managerId);if($s->execute()){$s->close();set_flash('success','Stakeholder added','The stakeholder has been added to the programme register.');safe_redirect('programme/stakeholders.php');}$s->close();}$errors[]='The stakeholder could not be saved.';}
  }
 }
}
$stakeholders=[];$engagements=[];$stats=['stakeholders'=>0,'engagements'=>0,'open_actions'=>0,'overdue'=>0];
if($ready){$s=$conn->prepare('SELECT s.*,p.name programme_name,c.name cohort_name,(SELECT COUNT(*) FROM programme_stakeholder_engagements e WHERE e.stakeholder_id=s.id) engagement_count FROM programme_stakeholders s JOIN programmes p ON p.id=s.programme_id LEFT JOIN cohorts c ON c.id=s.cohort_id WHERE p.programme_manager_id=? ORDER BY s.updated_at DESC,s.stakeholder_name');if($s){$s->bind_param('i',$managerId);$s->execute();$stakeholders=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
 $s=$conn->prepare("SELECT e.*,s.stakeholder_name,s.organisation,p.name programme_name FROM programme_stakeholder_engagements e JOIN programme_stakeholders s ON s.id=e.stakeholder_id JOIN programmes p ON p.id=e.programme_id WHERE p.programme_manager_id=? ORDER BY e.engagement_date DESC,e.id DESC LIMIT 100");if($s){$s->bind_param('i',$managerId);$s->execute();$engagements=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
 $stats['stakeholders']=count($stakeholders);$stats['engagements']=count($engagements);foreach($engagements as $e1){if(in_array($e1['action_status'],['open','in_progress'],true))$stats['open_actions']++;if(($e1['action_due']??'')!==''&&$e1['action_due']<date('Y-m-d')&&!in_array($e1['action_status'],['completed','not_required'],true))$stats['overdue']++;}}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($pageTitle)?> | Investhood IT</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css"><link rel="stylesheet" href="<?=url('css/styles.css')?>"><link rel="stylesheet" href="<?=url('css/programme_manager_enhancements.css')?>"><link rel="stylesheet" href="<?=url('css/programme_management_suite.css')?>?v=20261125"></head><body class="dashboard-page"><div class="dashboard"><?php require __DIR__.'/sidebar.php';?><main class="dashboard__main"><?php require __DIR__.'/navbar.php';?><div class="pm-suite"><?=$flashes?><section class="pm-suite-hero"><div><span class="pm-suite-eyebrow">Relationships &amp; collaboration</span><h1>Programme Stakeholder Management</h1><p>Maintain stakeholder relationships, capture engagement history and track contributions and follow-up actions across your assigned programmes.</p></div></section><?php foreach($errors as $error):?><div class="pm-suite-alert"><?=e($error)?></div><?php endforeach;?><?php if(!$ready):?><div class="pm-suite-notice">Import <code>database/programme_stakeholder_benefits.sql</code> to enable stakeholder and engagement tracking.</div><?php endif;?>
<section class="pm-suite-kpis"><article class="pm-suite-kpi"><small>Stakeholders</small><strong><?=$stats['stakeholders']?></strong><span>In assigned programmes</span></article><article class="pm-suite-kpi"><small>Engagement records</small><strong><?=$stats['engagements']?></strong><span>Recent records shown below</span></article><article class="pm-suite-kpi"><small>Open actions</small><strong><?=$stats['open_actions']?></strong><span>Awaiting completion</span></article><article class="pm-suite-kpi"><small>Overdue actions</small><strong><?=$stats['overdue']?></strong><span>Past due and not completed</span></article></section>
<div class="pm-suite-grid"><section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Add a stakeholder</h2><p>Associate each stakeholder with a programme and, where relevant, a cohort.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><input type="hidden" name="action" value="create_stakeholder"><div class="pm-suite-field"><label>Programme</label><select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $p):?><option value="<?=$p['id']?>"><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Cohort (optional)</label><select name="cohort_id"><option value="0">Programme-wide</option><?php foreach($cohorts as $c):?><option value="<?=$c['id']?>"><?=e($c['programme_name'].' — '.$c['name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Stakeholder name</label><input name="stakeholder_name" maxlength="160" required></div><div class="pm-suite-field"><label>Organisation</label><input name="organisation" maxlength="160"></div><div class="pm-suite-field"><label>Stakeholder type</label><select name="stakeholder_type"><?php foreach($types as $t):?><option><?=e($t)?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Role / responsibility</label><input name="role_responsibility" maxlength="180"></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Email</label><input type="email" name="email" maxlength="190"></div><div class="pm-suite-field"><label>Phone</label><input name="phone" maxlength="60"></div></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Influence</label><select name="influence_level"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></div><div class="pm-suite-field"><label>Interest</label><select name="interest_level"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></div></div><div class="pm-suite-field"><label>Notes</label><textarea name="notes" rows="3" maxlength="5000"></textarea></div><button class="pm-suite-btn" type="submit" <?=$ready?'':'disabled'?>>Save stakeholder</button></form></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Record an engagement</h2><p>Record communication, contribution and any action that needs follow-up.</p></div><form method="post" class="pm-suite-form"><?=csrf_field()?><input type="hidden" name="action" value="record_engagement"><div class="pm-suite-field"><label>Stakeholder</label><select name="stakeholder_id" required><option value="">Select stakeholder</option><?php foreach($stakeholders as $st):?><option value="<?=$st['id']?>"><?=e($st['stakeholder_name'].' — '.$st['programme_name'])?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Date and time</label><input type="datetime-local" name="engagement_date" value="<?=date('Y-m-d\TH:i')?>" required></div><div class="pm-suite-field"><label>Channel</label><select name="channel"><?php foreach($channels as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></div><div class="pm-suite-field"><label>Subject</label><input name="subject" maxlength="180" required></div><div class="pm-suite-field"><label>Engagement summary</label><textarea name="engagement_summary" rows="3" maxlength="5000"></textarea></div><div class="pm-suite-field"><label>Stakeholder contribution</label><textarea name="contribution" rows="2" maxlength="3000" placeholder="Advice, resources, decisions, referrals, support..."></textarea></div><div class="pm-suite-field"><label>Outstanding action (optional)</label><input name="action_required" maxlength="255"></div><div class="pm-suite-two"><div class="pm-suite-field"><label>Action owner</label><input name="action_owner" maxlength="160"></div><div class="pm-suite-field"><label>Action due date</label><input type="date" name="action_due"></div></div><button class="pm-suite-btn" type="submit" <?=$ready&&$stakeholders?'':'disabled'?>>Save engagement</button></form></section></div>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Stakeholder register</h2><p>Stakeholder relationships and recorded engagement totals.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Stakeholder</th><th>Programme / Cohort</th><th>Responsibility</th><th>Contact</th><th>Influence / Interest</th><th>Engagements</th></tr></thead><tbody><?php if(!$stakeholders):?><tr><td colspan="6" class="pm-suite-empty">No stakeholders have been added yet.</td></tr><?php else:foreach($stakeholders as $st):?><tr><td><strong><?=e($st['stakeholder_name'])?></strong><span class="pm-suite-muted"><?=e($st['stakeholder_type'].' · '.($st['organisation']?:'No organisation'))?></span></td><td><?=e($st['programme_name'])?><span class="pm-suite-muted"><?=e($st['cohort_name']??'Programme-wide')?></span></td><td><?=e($st['role_responsibility']?:'—')?></td><td><?=e($st['email']?:'—')?><span class="pm-suite-muted"><?=e($st['phone']?:'')?></span></td><td><?=e(ucfirst($st['influence_level']).' / '.ucfirst($st['interest_level']))?></td><td><strong><?=$st['engagement_count']?></strong></td></tr><?php endforeach;endif;?></tbody></table></div></section>
<section class="pm-suite-panel"><div class="pm-suite-panel-head"><h2>Engagement history &amp; action tracker</h2><p>Latest 100 engagements across your assigned programmes.</p></div><div class="pm-suite-table-wrap"><table class="pm-suite-table"><thead><tr><th>Date / Stakeholder</th><th>Engagement</th><th>Contribution</th><th>Action / Owner</th><th>Due / Status</th></tr></thead><tbody><?php if(!$engagements):?><tr><td colspan="5" class="pm-suite-empty">No engagement activity recorded.</td></tr><?php else:foreach($engagements as $eg):$late=($eg['action_due']??'')!==''&&$eg['action_due']<date('Y-m-d')&&!in_array($eg['action_status'],['completed','not_required'],true);?><tr><td><strong><?=e(date('d M Y H:i',strtotime($eg['engagement_date'])))?></strong><span class="pm-suite-muted"><?=e($eg['stakeholder_name'].' · '.$eg['programme_name'])?></span></td><td><strong><?=e($eg['subject'])?></strong><span class="pm-suite-muted"><?=e(ucwords(str_replace('_',' ',$eg['channel'])))?> · <?=e($eg['engagement_summary']?:'No summary')?></span></td><td><?=e($eg['contribution']?:'—')?></td><td><?=e($eg['action_required']?:'No follow-up action')?><span class="pm-suite-muted"><?=e($eg['action_owner']?:'')?></span></td><td><?=e($eg['action_due']?date('d M Y',strtotime($eg['action_due'])):'—')?><?php if($eg['action_required']):?><form method="post" class="pm-suite-actions"><?=csrf_field()?><input type="hidden" name="action" value="update_action"><input type="hidden" name="engagement_id" value="<?=$eg['id']?>"><select name="action_status" aria-label="Action status"><option value="open" <?=$eg['action_status']==='open'?'selected':''?>>Open</option><option value="in_progress" <?=$eg['action_status']==='in_progress'?'selected':''?>>In progress</option><option value="completed" <?=$eg['action_status']==='completed'?'selected':''?>>Completed</option><option value="overdue" <?=$late||$eg['action_status']==='overdue'?'selected':''?>>Overdue</option></select><button class="pm-suite-btn secondary" type="submit">Update</button></form><?php else:?><span class="pm-suite-pill info">No action</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></main></div><script src="<?=url('js/programme_manager_enhancements.js')?>"></script><script src="<?=url('js/original_pm_sidebar.js')?>"></script></body></html>
